#!/bin/sh
#
# faux-claude.sh — imite `claude -p --input-format stream-json --output-format stream-json` pour
# éprouver relais.sh et le moteur sans Claude ni quota : une ligne init, puis pour chaque message
# reçu, un texte partiel, un message avec un appel d'outil, son résultat (avec l'image
# $FAUX_IMAGE_B64), un relevé du forfait et un result. Écrit ses arguments dans arguments.txt
# (dans son dossier de travail). Un message « ARRETE-TOI » le fait quitter avec le code 3, une
# demande d'interruption répond comme Claude Code. Un message « NOTE-LES » propose des notes
# (propose_ratings, passe 2 : 3 étoiles, un rejet à vérifier, une photo
# refusée par le module) et reçoit la réponse du connecteur, en JSON. Un message « LECON » finit
# par la leçon de la photo (photo_lesson, trois points dans le désordre : composition d'abord) et
# reçoit la réponse du connecteur, en JSON (leçon rangée pour DSCF4961.RAF).
# Un message « Je le fais » range la version de Claude (preview_settings avec my_turn, rien
# d'appliqué) et reçoit la liste a_faire du connecteur, en JSON ; « J'ai fini » la compare
# (view_photo avec compare = claude_version) et reçoit l'image côte à côte, l'exercice en JSON et
# une remarque de l'écran à part (réponses du connecteur sur l'exemple RAW de
# Tests/Contrats/je-le-fais.json, pour la photo 53636309).

printf '%s\n' "$@" > arguments.txt
session=session-essai
[ -n "$ANTHROPIC_API_KEY" ] && echo "cle-api-presente" >> arguments.txt
printf '%s\n' '{"type":"system","subtype":"init","session_id":"'$session'","model":"claude-essai","mcp_servers":[{"name":"developpeur","status":"connected"}],"tools":[]}'
while IFS= read -r ligne; do
    case "$ligne" in
        *control_request*)
            printf '%s\n' '{"type":"control_response","response":{"subtype":"success","request_id":"interruption-1"}}'
            printf '%s\n' '{"type":"result","subtype":"error_during_execution","is_error":true,"session_id":"'$session'"}' ;;
        *ARRETE-TOI*)
            echo "panne simulée" >&2
            exit 3 ;;
        *LENT*)
            printf '%s\n' '{"type":"stream_event","event":{"type":"content_block_delta","delta":{"type":"text_delta","text":"Je réfléchis"}}}'
            sleep 30 ;;
        *NOTE-LES*)
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"Je propose les notes de la passe 2."},{"type":"tool_use","id":"outil-notes","name":"mcp__developpeur__propose_ratings","input":{"pass":2,"ratings":[{"photo_id":53636309,"rating":3,"criteria":{"impact":"Moyen : le flamant se voit d’abord.","qualities":"Lumière douce, sujet clair.","technical_floor":"Nette (44)."},"reason":"Tient seule.","to_check":false},{"photo_id":53636310,"flag":"reject","criteria":{"impact":"Aucun.","qualities":"Sujet coupé.","technical_floor":"Floue (9)."},"reason":"Flou de bougé involontaire.","to_check":true},{"photo_id":53636311,"rating":2,"criteria":{"impact":"Faible.","qualities":"Fond chargé.","technical_floor":"Douce (28)."},"reason":"Correcte, sans plus."}]}}]}}'
            printf '%s\n' '{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"outil-notes","content":[{"type":"text","text":"{\"propositions\": [{\"photo\": 53636309, \"fichier\": \"DSCF4961.RAF\", \"note_avant\": 0, \"drapeau_avant\": \"aucun\", \"etat\": \"proposee\"}, {\"photo\": 53636310, \"fichier\": \"DSCF4962.RAF\", \"note_avant\": 2, \"drapeau_avant\": \"aucun\", \"etat\": \"proposee\"}], \"refusees\": [{\"photo\": 53636311, \"raison\": \"photo introuvable\"}]}"}]}]}}'
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"Deux notes proposées ; la photo 53636311 est introuvable."}]}}'
            printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"result":"ok","session_id":"'$session'","duration_ms":900,"num_turns":2,"usage":{"input_tokens":12,"output_tokens":30},"modelUsage":{"claude-essai":{}}}' ;;
        *LECON*)
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"- Ciel retrouvé : 3 → 0,2 % écrêté.\n- Balance neutre."},{"type":"tool_use","id":"outil-lecon","name":"mcp__developpeur__photo_lesson","input":{"photo_id":53636309,"points":[{"axis":"composition","at_capture":"Le flamant au tiers gauche, regard vers le cadre : à refaire.","defects":[]},{"axis":"light","missing":"Ciel **brûlé** à 3 % : hautes lumières baissées de 40.","at_capture":"Compenser de −2/3 IL face au ciel clair.","defects":["blown_highlights"]},{"axis":"color","missing":"Dominante bleue à l’ombre : +400 K.","at_capture":"Balance des blancs Ombre plutôt qu’Auto.","defects":["color_cast"]}]}}]}}'
            printf '%s\n' '{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"outil-lecon","content":[{"type":"text","text":"{\n  \"faits\": {\"corrections\": []},\n  \"lecon\": {\"fichier\": \"DSCF4961.RAF\", \"mois\": \"2026-10\", \"photo\": 53636309, \"rangee\": true, \"remplacee\": false},\n  \"remarques\": [],\n  \"texte\": \"Leçon de la photo · DSCF4961.RAF\"\n}"}]}]}}'
            printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"result":"ok","session_id":"'$session'","duration_ms":800,"num_turns":2,"usage":{"input_tokens":11,"output_tokens":25},"modelUsage":{"claude-essai":{}}}' ;;
        *"Je le fais"*)
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"Je range ma version sans rien appliquer."},{"type":"tool_use","id":"outil-tour","name":"mcp__developpeur__preview_settings","input":{"photo_id":53636309,"settings":{"Exposure2012":0.35,"Vibrance":10,"Temperature":5600,"Contrast2012":10},"tone_curve":{"rgb":[[0,0],[128,140],[255,255]]},"my_turn":true,"step_name":"lumière et couleur"}}]}}'
            printf '%s\n' '{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"outil-tour","content":[{"type":"text","text":"{\n  \"a_faire\": [\n    {\n      \"a\": \"5 600 K\",\n      \"apres\": 5600,\n      \"avant\": 5350,\n      \"cle\": \"Temperature\",\n      \"de\": \"5 350 K\",\n      \"n\": 1,\n      \"panneau\": \"Réglages de base\",\n      \"reglage\": \"Température\",\n      \"section\": \"Balance des blancs\",\n      \"texte\": \"Réglages de base › Balance des blancs › Température : 5 350 K → 5 600 K\"\n    },\n    {\n      \"a\": \"+0,35\",\n      \"apres\": 0.35,\n      \"avant\": 0,\n      \"cle\": \"Exposure2012\",\n      \"de\": \"0\",\n      \"n\": 2,\n      \"panneau\": \"Réglages de base\",\n      \"reglage\": \"Exposition\",\n      \"section\": \"Tonalité\",\n      \"texte\": \"Réglages de base › Tonalité › Exposition : 0 → +0,35\"\n    },\n    {\n      \"a\": \"+10\",\n      \"apres\": 10,\n      \"avant\": 0,\n      \"cle\": \"Contrast2012\",\n      \"de\": \"0\",\n      \"n\": 3,\n      \"panneau\": \"Réglages de base\",\n      \"reglage\": \"Contraste\",\n      \"section\": \"Tonalité\",\n      \"texte\": \"Réglages de base › Tonalité › Contraste : 0 → +10\"\n    },\n    {\n      \"a\": \"+10\",\n      \"apres\": 10,\n      \"avant\": 0,\n      \"cle\": \"Vibrance\",\n      \"de\": \"0\",\n      \"n\": 4,\n      \"panneau\": \"Réglages de base\",\n      \"reglage\": \"Vibrance\",\n      \"section\": \"Présence\",\n      \"texte\": \"Réglages de base › Présence › Vibrance : 0 → +10\"\n    },\n    {\n      \"a\": \"3 points\",\n      \"apres\": \"3 points\",\n      \"avant\": \"linéaire\",\n      \"cle\": \"ToneCurvePV2012\",\n      \"de\": \"linéaire\",\n      \"n\": 5,\n      \"panneau\": \"Courbe des tonalités\",\n      \"reglage\": \"Courbe par points : RVB\",\n      \"section\": null,\n      \"texte\": \"Courbe des tonalités › Courbe par points › RVB : linéaire → 3 points\"\n    }\n  ],\n  \"base\": \"a_faire : dans l'\''ordre des panneaux du module Développement ; « de » : la valeur actuelle, « a » : celle de Claude ; texte : panneau › section › réglage. Réglages globaux seulement.\",\n  \"ensuite\": \"Quand l'\''utilisateur a fini : view_photo avec compare = claude_version.\",\n  \"etape\": \"Claude · essai : ma version (je le fais)\",\n  \"instantane\": \"Claude · ma version\",\n  \"mode\": \"appliquer directement\",\n  \"photo\": {\n    \"copie_virtuelle\": true,\n    \"fichier\": \"DSCF4961.RAF\",\n    \"id\": 53636309\n  },\n  \"rien_n_est_applique\": \"La photo est restée comme avant : la version de Claude est rangée en instantané « Claude · ma version » (choose_variant « ma version » la pose, seulement si l'\''utilisateur le demande).\"\n}"}]}]}}'
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"À vous : cinq réglages, dans l’ordre du panneau Développement."}]}}'
            printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"result":"ok","session_id":"'$session'","duration_ms":700,"num_turns":2,"usage":{"input_tokens":9,"output_tokens":21},"modelUsage":{"claude-essai":{}}}' ;;
        *"J'ai fini"*)
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"Je compare votre version à la mienne."},{"type":"tool_use","id":"outil-comparaison","name":"mcp__developpeur__view_photo","input":{"photo_id":53636309,"compare":"claude_version"}}]}}'
            printf '{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"outil-comparaison","content":[{"type":"image","source":{"type":"base64","media_type":"image/jpeg","data":"%s"}},{"type":"text","text":"[Image: source: /tmp/x.jpg]"},{"type":"text","text":"{\\n  \\"bilan\\": {\\n    \\"depuis\\": \\"ma version (Claude, à gauche)\\"\\n  },\\n  \\"exercice\\": {\\n    \\"a_savoir_exercice\\": \\"Ce que l'\''utilisateur a ajouté ou changé à la main (masques) se voit dans les deux images : la version de Claude ne peut pas le retirer le temps du rendu (la photo en portait déjà au départ).\\",\\n    \\"comme_claude\\": [\\n      \\"Préréglage\\",\\n      \\"Température\\"\\n    ],\\n    \\"ecart_principal\\": {\\n      \\"claude\\": 42.4,\\n      \\"ecart\\": 1.05,\\n      \\"fois_le_seuil\\": 10.4,\\n      \\"mesure\\": \\"exposition\\",\\n      \\"reglage\\": {\\n        \\"claude\\": 0.35,\\n        \\"cle\\": \\"Exposure2012\\",\\n        \\"depart\\": 0,\\n        \\"panneau\\": \\"Réglages de base\\",\\n        \\"reglage\\": \\"Exposition\\",\\n        \\"section\\": \\"Tonalité\\",\\n        \\"sorte\\": \\"plus_fort\\",\\n        \\"texte\\": \\"Réglages de base › Tonalité › Exposition : départ 0, Claude +0,35, vous +0,8 — plus fort que Claude\\",\\n        \\"vous\\": 0.8\\n      },\\n      \\"seuil\\": 0.1,\\n      \\"texte\\": \\"Votre version est plus claire de 1,04 IL (visible dès 0,1 IL). Le réglage qui l'\''explique le mieux : Réglages de base › Tonalité › Exposition : départ 0, Claude +0,35, vous +0,8 — plus fort que Claude.\\",\\n      \\"visible\\": true,\\n      \\"vous\\": 58.3\\n    },\\n    \\"ecarts\\": [\\n      {\\n        \\"claude\\": \\"Adobe Color\\",\\n        \\"cle\\": \\"Look\\",\\n        \\"depart\\": \\"Adobe Color\\",\\n        \\"panneau\\": \\"Réglages de base\\",\\n        \\"reglage\\": \\"Profil (Look)\\",\\n        \\"section\\": \\"Profil\\",\\n        \\"sorte\\": \\"ajoute\\",\\n        \\"texte\\": \\"Réglages de base › Profil › Profil (Look) : départ Adobe Color, Claude Adobe Color, vous aucune — ajouté par vous (Claude n'\''y touchait pas)\\",\\n        \\"vous\\": \\"aucune\\"\\n      },\\n      {\\n        \\"claude\\": \\"Custom\\",\\n        \\"cle\\": \\"WhiteBalance\\",\\n        \\"depart\\": \\"As Shot\\",\\n        \\"panneau\\": \\"Réglages de base\\",\\n        \\"reglage\\": \\"Préréglage\\",\\n        \\"section\\": \\"Balance des blancs\\",\\n        \\"sorte\\": \\"comme_claude\\",\\n        \\"texte\\": \\"Réglages de base › Balance des blancs › Préréglage : départ Telle quelle, Claude Personnalisée, vous Personnalisée — comme Claude\\",\\n        \\"vous\\": \\"Custom\\"\\n      },\\n      {\\n        \\"claude\\": 5600,\\n        \\"cle\\": \\"Temperature\\",\\n        \\"depart\\": 5350,\\n        \\"panneau\\": \\"Réglages de base\\",\\n        \\"reglage\\": \\"Température\\",\\n        \\"section\\": \\"Balance des blancs\\",\\n        \\"sorte\\": \\"comme_claude\\",\\n        \\"texte\\": \\"Réglages de base › Balance des blancs › Température : départ 5 350 K, Claude 5 600 K, vous 5 650 K — comme Claude\\",\\n        \\"vous\\": 5650\\n      },\\n      {\\n        \\"claude\\": 0.35,\\n        \\"cle\\": \\"Exposure2012\\",\\n        \\"depart\\": 0,\\n        \\"panneau\\": \\"Réglages de base\\",\\n        \\"reglage\\": \\"Exposition\\",\\n        \\"section\\": \\"Tonalité\\",\\n        \\"sorte\\": \\"plus_fort\\",\\n        \\"texte\\": \\"Réglages de base › Tonalité › Exposition : départ 0, Claude +0,35, vous +0,8 — plus fort que Claude\\",\\n        \\"vous\\": 0.8\\n      },\\n      {\\n        \\"claude\\": 10,\\n        \\"cle\\": \\"Contrast2012\\",\\n        \\"depart\\": 0,\\n        \\"panneau\\": \\"Réglages de base\\",\\n        \\"reglage\\": \\"Contraste\\",\\n        \\"section\\": \\"Tonalité\\",\\n        \\"sorte\\": \\"oublie\\",\\n        \\"texte\\": \\"Réglages de base › Tonalité › Contraste : départ 0, Claude +10, vous 0 — pas fait (Claude l'\''avait changé)\\",\\n        \\"vous\\": 0\\n      },\\n      {\\n        \\"claude\\": 0,\\n        \\"cle\\": \\"Clarity2012\\",\\n        \\"depart\\": 0,\\n        \\"panneau\\": \\"Réglages de base\\",\\n        \\"reglage\\": \\"Clarté\\",\\n        \\"section\\": \\"Présence\\",\\n        \\"sorte\\": \\"ajoute\\",\\n        \\"texte\\": \\"Réglages de base › Présence › Clarté : départ 0, Claude 0, vous +20 — ajouté par vous (Claude n'\''y touchait pas)\\",\\n        \\"vous\\": 20\\n      },\\n      {\\n        \\"claude\\": 10,\\n        \\"cle\\": \\"Vibrance\\",\\n        \\"depart\\": 0,\\n        \\"panneau\\": \\"Réglages de base\\",\\n        \\"reglage\\": \\"Vibrance\\",\\n        \\"section\\": \\"Présence\\",\\n        \\"sorte\\": \\"oublie\\",\\n        \\"texte\\": \\"Réglages de base › Présence › Vibrance : départ 0, Claude +10, vous 0 — pas fait (Claude l'\''avait changé)\\",\\n        \\"vous\\": 0\\n      },\\n      {\\n        \\"claude\\": \\"changée\\",\\n        \\"cle\\": \\"ToneCurvePV2012\\",\\n        \\"depart\\": \\"inchangée\\",\\n        \\"panneau\\": \\"Courbe des tonalités\\",\\n        \\"reglage\\": \\"Courbe par points : RVB\\",\\n        \\"section\\": null,\\n        \\"sorte\\": \\"autre_choix\\",\\n        \\"texte\\": \\"Courbe des tonalités › Courbe par points › RVB : Claude changée, vous changée autrement — un autre choix que Claude\\",\\n        \\"vous\\": \\"changée autrement\\"\\n      },\\n      {\\n        \\"claude\\": {\\n          \\"CropLeft\\": 0,\\n          \\"CropRight\\": 1,\\n          \\"CropTop\\": 0\\n        },\\n        \\"cle\\": \\"Crop\\",\\n        \\"cles\\": [\\n          \\"CropLeft\\",\\n          \\"CropRight\\",\\n          \\"CropTop\\"\\n        ],\\n        \\"depart\\": {\\n          \\"CropLeft\\": 0,\\n          \\"CropRight\\": 1,\\n          \\"CropTop\\": 0\\n        },\\n        \\"panneau\\": \\"Recadrage\\",\\n        \\"reglage\\": \\"Cadre\\",\\n        \\"section\\": null,\\n        \\"sorte\\": \\"ajoute\\",\\n        \\"texte\\": \\"Recadrage › Cadre : départ sans rognage ; Claude sans rognage ; vous rogné à gauche 5 %%, en haut 2 %%, à droite 5 %% — ajouté par vous (Claude n'\''y touchait pas)\\",\\n        \\"vous\\": {\\n          \\"CropLeft\\": 0.05,\\n          \\"CropRight\\": 0.95,\\n          \\"CropTop\\": 0.02\\n        }\\n      }\\n    ],\\n    \\"instantane\\": \\"Claude · ma version\\",\\n    \\"le\\": \\"2026-10-21 10:00\\",\\n    \\"listes\\": {\\n      \\"masques\\": {\\n        \\"depart\\": 1,\\n        \\"vous\\": 2\\n      },\\n      \\"taches\\": {\\n        \\"depart\\": 0,\\n        \\"vous\\": 0\\n      },\\n      \\"yeux_rouges\\": {\\n        \\"depart\\": 0,\\n        \\"vous\\": 0\\n      }\\n    },\\n    \\"restent\\": [\\n      \\"MaskGroupBasedCorrections\\"\\n    ],\\n    \\"resume\\": \\"9 réglages comparés : 2 comme Claude, 1 plus fort, 2 oubliés, 3 ajoutés, 1 autre choix.\\",\\n    \\"rien_change\\": false\\n  },\\n  \\"image\\": \\"À gauche ma version (Claude), à droite la vôtre.\\",\\n  \\"photo\\": {\\n    \\"copie_virtuelle\\": true,\\n    \\"fichier\\": \\"DSCF4961.RAF\\",\\n    \\"id\\": 53636309\\n  }\\n}"},{"type":"text","text":"Écran : profil d’usine, non étalonné : dis-le une fois si tu demandes son avis sur les couleurs."}]}]}}\n' "$(cat "$FAUX_IMAGE_B64")"
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"Bien vu pour la balance ; votre version est plus claire de 1 IL."}]}}'
            printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"result":"ok","session_id":"'$session'","duration_ms":900,"num_turns":2,"usage":{"input_tokens":9,"output_tokens":21},"modelUsage":{"claude-essai":{}}}' ;;
        *)
            printf '%s\n' '{"type":"stream_event","event":{"type":"content_block_delta","delta":{"type":"text_delta","text":"[titre : Flamant"}}}'
            printf '%s\n' '{"type":"stream_event","event":{"type":"content_block_delta","delta":{"type":"text_delta","text":" rose au zoo]\nBonjour"}}}'
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"[titre : Flamant rose au zoo]\nBonjour, je regarde la photo."},{"type":"tool_use","id":"outil-1","name":"mcp__developpeur__view_photo","input":{"photo_id":53636309}}]}}'
            printf '{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"outil-1","content":[{"type":"text","text":"{\\"exposition\\":0.2}"},{"type":"image","source":{"type":"base64","media_type":"image/jpeg","data":"%s"}},{"type":"text","text":"[Image: source: /tmp/x.jpg]"}]}]}}\n' "$(cat "$FAUX_IMAGE_B64")"
            printf '%s\n' '{"type":"rate_limit_event","rate_limit_info":{"unifiedWindows":{"five_hour":{"utilization":0.23},"seven_day":{"utilization":0.41,"resetsAt":1790000000}}}}'
            printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"## Diagnostic\n- **Exposition** : juste\n- Dominante chaude"}]}}'
            printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"result":"ok","session_id":"'$session'","duration_ms":1200,"num_turns":2,"usage":{"input_tokens":10,"output_tokens":20},"modelUsage":{"claude-essai":{}}}' ;;
    esac
done
